from flask import Flask, jsonify, request


def create_app():
    app = Flask(__name__)
    items = []

    @app.get("/health")
    def health():
        return jsonify(status="ok")

    @app.post("/items")
    def add_item():
        data = request.get_json(silent=True) or {}
        name = data.get("name")
        if not name:
            return jsonify(error="name is required"), 400
        item = {"id": len(items) + 1, "name": name}
        items.append(item)
        return jsonify(item), 201

    @app.get("/items")
    def list_items():
        return jsonify(items)

    return app

import pytest

from app import create_app


@pytest.fixture
def client():
    app = create_app()
    app.config["TESTING"] = True
    with app.test_client() as c:
        yield c


def test_health(client):
    resp = client.get("/health")
    assert resp.status_code == 200
    assert resp.get_json() == {"status": "ok"}


def test_add_item(client):
    resp = client.post("/items", json={"name": "widget"})
    assert resp.status_code == 201
    assert resp.get_json() == {"id": 1, "name": "widget"}


def test_add_item_requires_name(client):
    resp = client.post("/items", json={})
    assert resp.status_code == 400


def test_list_items(client):
    client.post("/items", json={"name": "a"})
    client.post("/items", json={"name": "b"})
    resp = client.get("/items")
    assert resp.status_code == 200
    assert resp.get_json() == [{"id": 1, "name": "a"}, {"id": 2, "name": "b"}]
